import React from 'react';

// JNV Pachpadra Official Emblem Asset
// Inline Data URI guarantees immediate 0ms offline rendering without external network requests.
export const JNV_LOGO_JPG = 'data:image/jpeg;base64,' + '';
export const JNV_LOGO_PNG = 'data:image/png;base64,' + '';

export const JNV_LOGO = JNV_LOGO_PNG;
export const JNV_LOGO_FALLBACK = '/logo.png';

// Safe error handler that never loops
export const handleLogoError = (e: React.SyntheticEvent<HTMLImageElement, Event>) => {
  const target = e.currentTarget;
  target.onerror = null;
  if (target.src !== JNV_LOGO_JPG) {
    target.src = JNV_LOGO_JPG;
  }
};
